이벤트: onCompositionStart → () => { composition.current = true; setComposing(true); }
onCompositionEnd → () => { composition.current = false; setComposing(false); }
onChange → event => { const next = { ...session, drafts: { ...session.drafts, [topic.id]: { ...draft, memoId: answerId(event.target.value, draft?.strokes ?? []), body: event.target.value } } }; setSession(next); persist(next); setNotice(''); }
